 result={'buildSha256':BUILD_SHA,'passed':sum(c['passed'] for c in checks),'failed':sum(not c['passed'] for c in checks),'completed':failure is None,'failure':failure,'checks':checks,'uncaughtErrors':errors,'consoleWarnings':warnings,'externalRequests':requests,'scope':'Real Chromium WebGL2 via SwiftShader under Xvfb; document injection; explicit temporary storage; no hardware peripherals or browser-restart persistence claim.'}
